-- Experiment.ranBy: who ran the experiment ("user", or "agent:<name> on behalf
-- of <user>"). A real column, not dataJson, so "all experiments by this
-- runner" is an index seek instead of a JSON scan. Legacy rows stay NULL.
--
-- Mirrors the field and @@index in prisma/schema.prisma (and
-- prisma/schema.sqlite.prisma, generated by src/scripts/sync-sqlite-schema.ts).
--
-- Apply with: wrangler d1 migrations apply slashloop --remote
ALTER TABLE "Experiment" ADD COLUMN "ranBy" TEXT;
CREATE INDEX IF NOT EXISTS "Experiment_workspaceId_ranBy_createdAt_idx"
  ON "Experiment"("workspaceId", "ranBy", "createdAt");
